impl<'a> Lexer<'a> {
    /// Creates a new lexer for the given string.
    pub fn new(input: &'a str) -> Lexer<'a> {
        Self {
            chars: input.chars().peekable(),
        }
    }

    /// Returns the next character if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(char) -> bool) -> Option<char> {
        self.chars.next_if(predicate)
    }

    /// Applies a closure to the next character, returning its result and
    /// consuming the next character if it's Some.
    fn next_if_map<T>(&mut self, map: impl Fn(char) -> Option<T>) -> Option<T> {
        self.chars.next_if_map(map)
    }

    /// Returns true if the next character is the given character, consuming it.
    fn next_is(&mut self, c: char) -> bool {
        self.chars.next_if(|&ch| ch == c).is_some()
    }

    /// Scans the next token, if any.
    fn scan(&mut self) -> Result<Option<Token>> {
        self.scan_ident_or_keyword()
            .or_else(|| self.scan_ident_quoted().transpose())
            .or_else(|| self.scan_number())
            .or_else(|| self.scan_string().transpose())
            .or_else(|| self.scan_symbol())
            .map(Ok)
    }

    /// Scans the next identifier or keyword, if any. It's converted to
    /// lowercase, by SQL convention.
    fn scan_ident_or_keyword(&mut self) -> Option<Token> {
        let start = self.chars.peek()?;
        if !start.is_alphabetic() && *start != '_' {
            return None;
        }

        let mut ident = String::new();
        while let Some(&c) = self.chars.peek() {
            if c.is_alphanumeric() || c == '_' {
                ident.push(c);
                self.chars.next();
            } else {
                break;
            }
        }

        // Try to convert to keyword (case-insensitive)
        match Keyword::try_from(ident.as_str()) {
            Ok(keyword) => Some(Token::Keyword(keyword)),
            Err(_) => Some(Token::Ident(ident)),
        }
    }

    /// Scans the next quoted identifier, if any. Case is preserved.
    fn scan_ident_quoted(&mut self) -> Result<Option<Token>> {
        if !self.next_is('"') {
            return Ok(None);
        }

        let mut ident = String::new();
        loop {
            match self.chars.next() {
                Some('"') => break,
                Some(c) => ident.push(c),
                None => return errinput!("unexpected end of input in quoted identifier"),
            }
        }

        Ok(Some(Token::Ident(ident)))
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let start = self.chars.peek()?;
        if !start.is_ascii_digit() && *start != '.' {
            return None;
        }

        let mut num = String::new();

        // Handle optional leading minus (will be separate token, but we handle it here)
        if *start == '-' {
            num.push('-');
            self.chars.next();
        }

        // Integer part
        while let Some(&c) = self.chars.peek() {
            if c.is_ascii_digit() {
                num.push(c);
                self.chars.next();
            } else {
                break;
            }
        }

        // Decimal point and fractional part
        if self.next_is('.') {
            num.push('.');
            while let Some(&c) = self.chars.peek() {
                if c.is_ascii_digit() {
                    num.push(c);
                    self.chars.next();
                } else {
                    break;
                }
            }
        }

        // Exponent
        if let Some(&c) = self.chars.peek() {
            if c == 'e' || c == 'E' {
                num.push(c);
                self.chars.next();
                if let Some(&c) = self.chars.peek() {
                    if c == '+' || c == '-' {
                        num.push(c);
                        self.chars.next();
                    }
                }
                while let Some(&c) = self.chars.peek() {
                    if c.is_ascii_digit() {
                        num.push(c);
                        self.chars.next();
                    } else {
                        break;
                    }
                }
            }
        }

        Some(Token::Number(num))
    }

    /// Scans the next quoted string literal, if any.
    fn scan_string(&mut self) -> Result<Option<Token>> {
        if !self.next_is('\'') {
            return Ok(None);
        }

        let mut s = String::new();
        loop {
            match self.chars.next() {
                Some('\'') => {
                    // Check for escaped quote
                    if self.next_is('\'') {
                        s.push('\'');
                    } else {
                        break;
                    }
                }
                Some('\\') => {
                    // Handle escape sequences
                    match self.chars.next() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('\\') => s.push('\\'),
                        Some('\'') => s.push('\''),
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => {
                            return errinput!("unexpected end of input in string");
                        }
                    }
                }
                Some(c) => s.push(c),
                None => return errinput!("unexpected end of input in string"),
            }
        }

        Ok(Some(Token::String(s)))
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Option<Token> {
        let c = self.chars.peek()?;
        let token = match c {
            '.' => Token::Period,
            '=' => Token::Equal,
            '!' => {
                self.chars.next();
                if self.next_is('=') {
                    Token::NotEqual
                } else {
                    Token::Exclamation
                }
            }
            '>' => {
                self.chars.next();
                if self.next_is('=') {
                    Token::GreaterThanOrEqual
                } else {
                    Token::GreaterThan
                }
            }
            '<' => {
                self.chars.next();
                if self.next_is('=') {
                    Token::LessThanOrEqual
                } else if self.next_is('>') {
                    Token::LessOrGreaterThan
                } else {
                    Token::LessThan
                }
            }
            '+' => Token::Plus,
            '-' => Token::Minus,
            '*' => Token::Asterisk,
            '/' => Token::Slash,
            '^' => Token::Caret,
            '%' => Token::Percent,
            '?' => Token::Question,
            ',' => Token::Comma,
            ';' => Token::Semicolon,
            '(' => Token::OpenParen,
            ')' => Token::CloseParen,
            _ => return None,
        };
        self.chars.next();
        Some(token)
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while let Some(&c) = self.chars.peek() {
            if c.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }
}

